DIMENSION: to_string-composition — definitive spec after adversarial falsification (~1700 binary invocations).

=====================================================================
PART A — ENTRY / ARITY (needed to reach to_string at all)
=====================================================================
argv (excluding program name) = [scheme_arg, host_arg, port_arg, path_arg, query_arg, fragment_arg, ...ignored]

if (argc_user < 6):
    exit(1)                       // no stdout, no stderr, no output whatsoever
// argc_user > 6: surplus args are read and discarded; they change nothing.

=====================================================================
PART B — FIELD NORMALIZATION (inputs to the composition)
=====================================================================
// B1. scheme: ASCII-only lowercase, nothing else.
scheme = scheme_arg.map(b => (b >= 0x41 && b <= 0x5A) ? b + 0x20 : b)   // BYTE-wise
// Rust: scheme_arg.to_ascii_lowercase()  -- NOT to_lowercase(), NOT locale-aware.
// Bytes 0x80..0xFF, 0x5B..0x60, all punctuation/control: unchanged.

// B2. host: stored VERBATIM. No lowercasing, no trimming, no IPv6/bracket logic,
//     no splitting on '@' or ':' or '/'. Zero transformation of any byte.
host = host_arg

// B3. port: std::stoi(port_arg, nullptr, 10) then range-clamp.
//     stoi: skip leading isspace() (' ' \t \n \v \f \r), optional '+'/'-',
//           consume decimal digits, STOP at first non-digit, IGNORE the rest.
if (no digits were consumed):            // "", "abc", "-", "+", "  "
    abort: std::invalid_argument, exit code 134, stderr
    "terminate called after throwing an instance of 'std::invalid_argument'\n  what():  stoi"
    -> NOTHING is printed to stdout. to_string is never produced.
if (parsed value does not fit in int32):  // "2147483648", "-2147483649", "9999999999"
    abort: std::out_of_range, exit code 134, same shape of message, zero stdout.
p = <int32 value>
port = (p >= 0 && p <= 65535) ? p : -1    // 65536, 100000, 2147483647, -2, -2147483648 -> -1
// Examples: " 80"->80  "80 "->80  "8 0"->8  "0x50"->0  "1e3"->1  "65535.9"->65535
//           "65535x"->65535  "0000000000000000080"->80  "+00080"->80  "-0"->0  "-00"->0

// B4. path: single first-BYTE test, nothing more.
path = path_arg
if (!path.is_empty() && path[0] != b'/'):
    path = "/" + path
// No dot-segment removal, no trimming, no encoding, no collapsing of '//'.
// "/"->"/"  "//"->"//"  "///"->"///"  "p"->"/p"  " "->"/ "  "?x"->"/?x"  "\t/x"->"/\t/x"
// Applied unconditionally, independent of scheme/host/port.

// B5. query    = query_arg      // verbatim, zero transformation
// B6. fragment = fragment_arg   // verbatim, zero transformation

=====================================================================
PART C — to_string() COMPOSITION  (the dimension proper)
=====================================================================
fn to_string(scheme, host, port, path, query, fragment) -> String {
    let mut s = String::new();

    // ---- Block 1: AUTHORITY. Gated ONLY on scheme != "". ----
    if !scheme.is_empty() {
        s += scheme;                      // already ASCII-lowercased
        s += "://";                       // ONE unconditional literal; never just ":"
        s += host;                        // verbatim; emitted even if empty
        if port != -1 {                   // equivalently port >= 0, equivalently 0..=65535
            s += ":";
            s += &port.to_string();       // plain decimal, no padding, no '+'
        }
    }
    // If scheme == "", host AND port are BOTH completely absent from the output,
    // no matter how valid they are. There is no "//" without a scheme.

    // ---- Block 2: PATH. Unconditional, verbatim, no separator, no default. ----
    s += path;                            // NO '/' is inserted between authority and path
                                          // NO "/" is substituted when path is empty

    // ---- Block 3: QUERY ----
    if !query.is_empty() {                // whitespace-only IS non-empty
        s += "?";                         // added unconditionally; a leading '?' in the
        s += query;                       // argument is therefore DUPLICATED
    }

    // ---- Block 4: FRAGMENT (always last, after query) ----
    if !fragment.is_empty() {
        s += "#";                         // leading '#' likewise DUPLICATED
        s += fragment;
    }

    return s;                             // exactly these 4 blocks; nothing else is ever
}                                         // inserted: no userinfo, no '@', no escaping

// Corollaries (all observed):
//  * to_string() == ""  <=>  scheme=="" && path=="" && query=="" && fragment==""
//    (host and port are irrelevant to emptiness).
//  * to_string() is NEVER gated on is_valid(); invalid URLs compose normally.
//  * to_string() is a pure deterministic function of the 6 normalized fields.
//  * No length cap: len == 13 + 4n for n-length host/path/query/fragment, tested to n=60000.
//  * Byte-transparent: every byte 0x01-0xFF (incl. control chars and '\n') passes through
//    unmodified in every field. No percent-encoding, no filtering.

=====================================================================
PART D — OUTPUT FRAMING (corrected; the previously-claimed "always 8 lines" is FALSE)
=====================================================================
print!("{}\n{}\n{}\n{}\n{}\n{}\n{}\n{}\n",
       scheme, host, port, path, query, fragment, to_string(), is_valid() as u8);
// Exactly 8 FIELDS, each '\n'-terminated. Because '\n' inside a field is NOT escaped,
// physical stdout line count = 8 + (#'\n' in scheme+host+path+query+fragment)
//                                + (#'\n' inside the composed to_string).
// Observed: query=$'a\nb' with scheme set -> 10 lines; host=$'a\nb' with scheme=""
//           -> 9 lines (host newline on line 2 only, absent from to_string).

=====================================================================
PART E — EXACT LITERALS FOR THE SURPRISING CASES (all directly observed)
=====================================================================
("http","example.com","80","/","","")   -> "http://example.com:80/"      valid 1
("http","example.com","-1","/","","")   -> "http://example.com/"         valid 1
("http","example.com","0","/","","")    -> "http://example.com:0/"       valid 1   // port 0 IS printed
