("http","h","80","\t/x","","")          -> "http://h:80/\t/x"            valid 1   // path -> "/\t/x"
("http","h","80","/"," ","")            -> "http://h:80/? "              valid 1
("http","h","80","/","",""))            -> "http://h:80/"                          // no '?' or '#'
("http","h","80","/p",$'a\nb","")       -> "http://h:80/p?a\nb"                     // 10 stdout lines
